    let cancelled = false;
    async function restore() {
      try {
        const session = await loadSession();
        if (cancelled || !session) return;

        // 1. Instantly restore full multi-tab and split layout state if available
        const restoredState = deserializeWorkspaceState(activeProject.workspaceId, session);
        const liveSessions = await listTerminalSessions().catch(() => []);
        const liveBackendIds = new Set(liveSessions.map((s) => s.sessionId));

        if (restoredState && restoredState.layout.tabs.length > 0) {
          let stateNeedsUpdate = false;
          for (const sess of Object.values(restoredState.sessions)) {
            if (sess.backendSessionId && !liveBackendIds.has(sess.backendSessionId)) {
              sess.backendSessionId = null;
              stateNeedsUpdate = true;
            }
          }

          restoreWorkspace(restoredState);

          // For any session whose backend session is dead (e.g. after app restart), re-spawn
          const deadSessions = Object.values(restoredState.sessions).filter((s) => !s.backendSessionId);
          if (deadSessions.length > 0) {
            await ensureTerminalEvents().catch(() => undefined);
            for (const sess of deadSessions) {
